function validate([boxGrid]) {
  if (!Array.isArray(boxGrid) || boxGrid.length < 1 || boxGrid.length > 500) return 'boxGrid needs 1 to 500 rows.';
  const n = boxGrid[0].length;
  if (n < 1 || n > 500) return 'Each row needs 1 to 500 cells.';
  for (let i = 0; i < boxGrid.length; i++) {
    if (boxGrid[i].length !== n) return 'All rows must have the same length.';
    for (let j = 0; j < n; j++) {
      const cell = boxGrid[i][j];
      if (cell !== '#' && cell !== '*' && cell !== '.') return "Each cell is '#', '*' or '.'.";
      if (cell === '#' && i + 1 < boxGrid.length && boxGrid[i + 1][j] === '.') return 'Every stone must already rest on something below it.';
    }
  }
  return null;
}

