function rotateTheBox(boxGrid) {
  const m = boxGrid.length;
  const n = boxGrid[0].length;
  const result = Array.from({ length: n }, () => new Array(m).fill('.'));

  for (let i = 0; i < m; i++) {
    const col = m - 1 - i;
    let empty = n - 1;
    for (let j = n - 1; j >= 0; j--) {
      const cell = boxGrid[i][j];
      if (cell === '*') {
        result[j][col] = '*';
        empty = j - 1;
      } else if (cell === '#') {
        result[empty][col] = '#';
        empty--;
      }
    }
  }
  return result;
}

