function rotateTheBox(boxGrid) {
  const m = boxGrid.length, n = boxGrid[0].length;
  const turned = [];
  for (let r = 0; r < n; r++) {
    turned.push([]);
    for (let c = 0; c < m; c++) turned[r].push(boxGrid[m - 1 - c][r]);
  }
  let moved = true;
  while (moved) {
    moved = false;
    for (let r = n - 2; r >= 0; r--)
      for (let c = 0; c < m; c++)
        if (turned[r][c] === '#' && turned[r + 1][c] === '.') {
          turned[r][c] = '.';
          turned[r + 1][c] = '#';
          moved = true;
        }
  }
  return turned;
}

