function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 7);
  const stone = 0.2 + rand() * 0.4, wall = rand() * 0.25;
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => {
    const x = rand();
    return x < stone ? '#' : x < stone + wall ? '*' : '.';
  }));
  // The input must already be at rest, so let each column's stones settle downward first.
  for (let j = 0; j < n; j++) {
    let floor = m - 1;
    for (let i = m - 1; i >= 0; i--) {
      if (grid[i][j] === '*') floor = i - 1;
      else if (grid[i][j] === '#') { grid[i][j] = '.'; grid[floor][j] = '#'; floor--; }
    }
  }
  return [grid];
}
